-- Chain O' Lakes Companions
UPDATE breeder_profiles SET description = 'Chain O'' Lakes Companions is a family-run Havanese breeder near LaGrange, Indiana, run by Perry and Sharon Kuhns and their five children. They raise one or two litters at a time, and both parents complete health screening before a litter is planned. Puppies are handled daily with the family and start learning to go potty outside before they go home. Each puppy leaves with a vet exam, current vaccinations, a microchip, a 30-day health guarantee and a 2-year genetic health guarantee. The family holds a USDA Class A license, welcomes visits by appointment and can talk through delivery for families farther away.', public_phone = '260-214-2113', public_email = 'adoptions@chainolakescompanions.com', city = 'LaGrange', state = 'IN', facebook_url = 'https://www.facebook.com/1111045712089952', updated_at = '2026-10-12T00:00:00Z', version = version + 1 WHERE breeder_id = 'seed-chainolakescompanions';
