-- Heartland Mini Schnauzers
UPDATE breeder_profiles SET description = 'Heartland Mini Schnauzers raises Miniature Schnauzers with a family near Millersburg, Indiana. They keep to one or two litters at a time, and the parents are health screened before a litter is planned. The puppies are handled every day and begin potty training outside before they go home. A vet exam, current vaccinations and a microchip come with each puppy, along with a 30-day health guarantee and a 2-year genetic health guarantee. Families can visit by appointment, and delivery or a halfway meetup can be arranged.', public_phone = '(574) 330-1133', public_email = 'adoptions@heartlandminischnauzers.com', city = 'Millersburg', state = 'IN', facebook_url = 'https://www.facebook.com/1196648593541538', updated_at = '2026-10-12T00:00:00Z', version = version + 1 WHERE breeder_id = 'seed-heartlandminischnauzers';
