-- Bless Your Paws Puppies
UPDATE breeder_profiles SET description = 'Bless Your Paws Puppies is run by twin sisters Hope and Joy, who raise Munchkin Bernedoodles in their home in northern Indiana. Puppies grow up in the house around nieces, nephews, other dogs and everyday family noise, and they get early neurological stimulation and start grass potty training before going home. Each puppy leaves with a vet exam, current vaccinations, a microchip and a written health guarantee. Visits are by appointment, video calls are welcome, and delivery can be arranged through their transport partner.', public_phone = '(574) 377-8023', public_email = 'info@blessyourpawspuppies.com', state = 'IN', updated_at = '2026-10-12T00:00:00Z', version = version + 1 WHERE breeder_id = 'seed-blessyourpawspuppies';
