-- Kingdom Family Companions
UPDATE breeder_profiles SET description = 'Kingdom Family Companions is a family in Milford, Indiana, who have raised dogs for more than 20 years. They began raising Golden Retrievers in 2024 and added Doberman Pinschers in early 2026. Puppies are raised in the northern Indiana countryside and taken to town for extra socialization. Parents are genetically tested and OFA certified, with results shared for each dog. Families are welcome to meet the puppies in person or by video call, and transportation can be arranged when needed.', public_phone = '260-306-9010', public_email = 'info@kingdomfamilycompanions.com', city = 'Milford', state = 'IN', updated_at = '2026-10-12T00:00:00Z', version = version + 1 WHERE breeder_id = 'seed-kingdomfamilycompanions';
