-- Winding Streams Companions
UPDATE breeder_profiles SET description = 'Winding Streams Companions is a family-run breeder on a dairy farm in Paradise, Pennsylvania, run by Benuel and Mary Stoltzfus and their six children. They raise Bernese Mountain Dogs, German Shepherds, Goldendoodles, Maltipoos, Miniature Poodles and Poodles, with one or two litters at a time. Parents are genetically tested and health screened before a litter is planned, and puppies are socialized daily and start learning to go potty outside before going home. Each puppy comes with a 30-day health guarantee and a 2-year genetic health guarantee. Visits are by appointment, and delivery or a midway meetup can be arranged.', public_phone = '717-786-3131', public_email = 'windingstreamscompanions@mailprint.net', city = 'Paradise', state = 'PA', facebook_url = 'https://www.facebook.com/profile.php?id=61579906093738', updated_at = '2026-10-12T00:00:00Z', version = version + 1 WHERE breeder_id = 'seed-windingstreamscompanions';
