UPDATE breeder_profiles SET description = 'Cornerstone Cavaliers is the Fry family''s Cavalier King Charles Spaniel program near Ligonier, Indiana. The family began breeding in 2021 because they loved the breed''s easygoing temperament, and their puppies are raised in the home on a 25-acre farm with six children, horses, ponies and chickens. Both parents complete health screening before a litter is planned, and puppies are handled daily. Each puppy leaves with a vet exam, vaccinations, a microchip, a 30-day health guarantee and a 2-year genetic health guarantee, and delivery or a midway meetup can be arranged.', public_phone = '260-465-6341', public_email = 'adoptions@cornerstonecavaliers.com', city = 'Ligonier', state = 'IN', facebook_url = 'https://www.facebook.com/1285223648012814', updated_at = '2026-10-12T00:00:00Z', version = version + 1 WHERE breeder_id = 'seed-cornerstonecavaliers';
